namespace ghidra.app.plugin.match;

using generic.stl;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.util.exception;
using ghidra.util.task;



public abstract class AbstractFunctionHasher : FunctionHasher {

	/* @Override */
	public long hash(Function function, TaskMonitor monitor)
    {
		Program program = function.getProgram();
		Pair<Integer, List<CodeUnit>> pair =
			getAllCodeUnits(monitor, program, new AddressSet(function.getBody()));
		try {
			return hash(monitor, pair.second, pair.first);
		}
		catch (MemoryAccessException e) {
			throw new RuntimeException(e);
		}
	}

	protected Pair<Integer, List<CodeUnit>> getAllCodeUnits(TaskMonitor monitor,
			Program prog, AddressSetView set) {
		int totalLength = 0;
		List<CodeUnit> arr = new List<CodeUnit>();
		CodeUnitIterator iter = prog.getListing().getCodeUnits(set, true);
		while (!monitor.isCancelled() && iter.hasNext()) {
			CodeUnit next = iter.next();
			arr.add(next);
			totalLength += next.getLength();
		}
		return new Pair<Integer, List<CodeUnit>>(totalLength, arr);

	}

	protected abstract long hash(TaskMonitor monitor, List<CodeUnit> units, int byteCount);
}
